import numpy as np

def feature(current, candidates, tour, start):
    """Negative Euclidean distance from current city to each candidate, scaled by the max such distance."""
    d = np.linalg.norm(candidates - current, axis=1)
    return -d / (d.max() + 1e-9)

import numpy as np

def feature(current, candidates, tour, start):
    """Cosine of the turn angle between the incoming direction of travel and each candidate direction."""
    if tour.shape[0] < 2:
        return np.zeros(candidates.shape[0])
    v_in = tour[-1] - tour[-2]
    v = candidates - current
    num = v @ v_in
    den = np.linalg.norm(v, axis=1) * np.linalg.norm(v_in) + 1e-9
    return num / den

import numpy as np

def feature(current, candidates, tour, start):
    """Negative distance-to-start, scaled by max, active only when k <= 5, weighted by (6-k)/5."""
    k = len(candidates)
    if k > 5:
        return np.zeros(k)
    d = np.linalg.norm(candidates - start, axis=1)
    dmax = d.max()
    scale = d / (dmax + 1e-9)
    return -scale * ((6 - k) / 5.0)

import numpy as np

def feature(current, candidates, tour, start):
    """Signed sine of the turn from the incoming direction to each candidate direction."""
    k = candidates.shape[0]
    if tour.shape[0] < 2:
        return np.zeros(k)
    inc = current - tour[-2]
    n_inc = np.sqrt(inc[0] * inc[0] + inc[1] * inc[1])
    if n_inc < 1e-12:
        return np.zeros(k)
    u = inc / n_inc
    d = candidates - current
    nd = np.sqrt(d[:, 0] * d[:, 0] + d[:, 1] * d[:, 1])
    nd = np.maximum(nd, 1e-12)
    sinv = (u[0] * d[:, 1] - u[1] * d[:, 0]) / nd
    return sinv

import numpy as np

def feature(current, candidates, tour, start):
    """Negative fraction of other unvisited cities lying radially beyond each candidate from the unvisited centroid."""
    k = candidates.shape[0]
    if k < 2:
        return np.zeros(k)
    cent = candidates.mean(axis=0)
    V = candidates - cent
    G = V @ V.T
    n2 = (V * V).sum(axis=1)
    beyond = (G > n2[:, None]).sum(axis=1)
    return -beyond / max(k, 1)
